 pub fn deny(self,j:&ModelTurnJournal)->Result<(),String>{log(j,&self.chat,&self.turn,K::Rejected,"HUMAN_DECLINED_PUBLICATION_SELECTION")}
 fn check(&self,j:&ModelTurnJournal,n:usize)->Result<Vec<crate::model_turn_journal::ModelAuditRecord>,String>{let r=j.events_for(&self.chat,&self.turn).map_err(|_|"Publication audit unavailable")?;if r.len()!=n||r[0].kind!=K::UserRequest||r[0].payload!=self.intent.original||r[1].kind!=K::ModelOutput||sha(r[1].payload.as_bytes())!=self.model_sha||r[2].kind!=K::ParsedCandidate||serde_json::from_str::<Value>(&r[2].payload).ok()!=Some(self.candidate()){return Err("Publication proposal audit differs".into())}Ok(r)}
